INSERT INTO public.recetas (titulo, descripcion, instrucciones, dificultad, tiempo_preparacion, porciones, imagen_url, categoria, activo)
VALUES
('Huevos Revueltos con Aguacate', 'No cocinar los huevos a fuego alto para evitar que se sequen. El aguacate debe estar maduro pero firme.', 'Picar el aguacate en cubos medianos y reservar.. Batir los huevos en un bowl con sal y pimienta al gusto.. Derretir la mantequilla en una sartén a fuego medio-bajo.. Verter los huevos batidos y cocinar removiendo suavemente con una espátula.. Cuando los huevos estén casi cocidos pero aún húmedos, retirar del fuego (continuarán cocinando con el calor residual).. Servir los huevos revueltos junto con el aguacate en cubos.. Sazonar con sal, pimienta y opcionalmente un poco de ajo en polvo.', 'fácil', 10, 1, 'https://images.pexels.com/photos/1893556/pexels-photo-1893556.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Tortilla Española de Espinacas', 'Esta tortilla puede comerse caliente o a temperatura ambiente. Es perfecta para preparar la noche anterior.', 'Lavar bien las espinacas y escurrir.. Batir los huevos con sal y pimienta.. Calentar la mantequilla en una sartén antiadherente.. Agregar las espinacas y cocinar 2 minutos hasta que se marchiten.. Verter los huevos batidos sobre las espinacas.. Cocinar a fuego bajo hasta que los bordes estén firmes.. Agregar el queso feta desmenuzado por encima.. Doblar la tortilla por la mitad y cocinar 1 minuto más.', 'fácil', 15, 1, 'https://images.pexels.com/photos/2286929/pexels-photo-2286929.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Huevos con Bacon Crujiente', 'Para huevos escalfados: hervir agua con un chorrito de vinagre, crear un remolino y añadir el huevo. Cocinar 3 minutos.', 'Calentar una sartén a fuego medio-alto.. Cocinar el bacon 3-4 minutos por lado hasta que esté crujiente.. Retirar el bacon y reservar sobre papel absorbente.. En la misma sartén con la grasa del bacon, derretir la mantequilla.. Cocinar los huevos fritos o escalfados a gusto.. Servir inmediatamente con el bacon crujiente.', 'fácil', 12, 1, 'https://images.pexels.com/photos/162967/pexels-photo-162967.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Omelette de Queso y Hierbas', 'Para una omelette más esponjosa, agregar una cucharada de agua o leche dentro de los huevos batidos.', 'Batir los huevos con sal, pimienta y hierbas opcionales (perejil, cebollino).. Derretir la mantequilla en una sartén a fuego medio.. Verter los huevos batidos y dejar cocinar sin mover por 1-2 minutos.. Cuando los bordes estén firmes pero el centro aún líquido, agregar el queso.. Doblar la omelette por la mitad y cocinar 30 segundos más.. Deslizar sobre el plato y servir inmediatamente.', 'fácil', 10, 1, 'https://images.pexels.com/photos/376464/pexels-photo-376464.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Yogur Griego con Frutos Rojos', 'Los frutos rojos frescos tienen menos carbohidratos que los congelados con azúcar. Elige moras, frambuesas o fresas con moderación.', 'Verter el yogur griego en un bowl o vaso alto.. Agregar las nueces y pecanas picadas.. Endulzar con eritritol al gusto si se desea.. Mezclar suavemente y disfrutar.. Opcional: agregar semillas de chía o coco rallado.', 'muy fácil', 5, 1, 'https://images.pexels.com/photos/298217/pexels-photo-298217.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Pancakes de Harina de Almendra', 'La masa debe tener consistencia espesa. Si está muy líquida, agregar más harina de almendra. No cocinar a fuego muy alto para evitar que se quemen.', 'Mezclar la harina de almendra con los huevos batidos hasta obtener una masa homogénea.. Agregar edulcorante si se desea.. Calentar mantequilla en una sartén a fuego medio.. Verter 1/4 de la mezcla formando un círculo.. Cocinar 2-3 minutos hasta que aparezcan burbujas.. Voltear con cuidado y cocinar 1-2 minutos más.. Repetir con el resto de la mezcla.. Servir con mantequilla y opcionalmente queso mozzarella derretido.', 'media', 15, 1, 'https://images.pexels.com/photos/1775043/pexels-photo-1775043.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Café Bulletproof Keto', 'Este café proporciona energía sostenida durante varias horas. No es necesario tomarlo todos los días, pero es excelente para el ayuno intermitente.', 'Preparar el café negro (puede ser expreso o café de filtro fuerte).. Calentar ligeramente la mantequilla y el aceite de coco.. Verter todo en una licuadora de alta potencia o usar batidora de leche.. Licuar durante 20-30 segundos hasta obtener una consistencia espumosa.. Verter en una taza y disfrutar inmediatamente.', 'muy fácil', 5, 1, 'https://images.pexels.com/photos/312418/pexels-photo-312418.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Quiche de Ajo y Queso', 'Se pueden preparar en batches y guardar en冰箱 hasta 3 días. Son perfectos para meal prep.', 'Precalentar el horno a 180°C.. Dorar el ajo picado en mantequilla hasta que esté fragante.. Batir los huevos con la nata, sal y pimienta.. Agregar el queso mozzarella rallado.. Verter la mezcla en moldes para muffins engrasados.. Hornear durante 15-18 minutos hasta que estén firmes.. Dejar enfriar 5 minutos antes de servir.', 'media', 20, 2, 'https://images.pexels.com/photos/7699696/pexels-photo-7699696.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Pechuga de Pollo con Brócoli', 'Para pollo más jugoso, marinar en aceite de oliva y ajo durante 30 minutos antes de cocinar. Usar termómetro: 74°C interno.', 'Sazonar la pechuga de pollo con sal, pimienta y especias al gusto.. Calentar el aceite de oliva en una sartén a fuego medio-alto.. Sellar el pollo 3-4 minutos por cada lado hasta dorar.. Reducir el fuego, tapar y cocinar 10-12 minutos más hasta que esté cocido.. Mientras tanto, cortar el brócoli en floretes y cocinar al vapor 5-6 minutos.. Cortar el pollo en rodajas y servir con el brócoli.. Rociar con un poco más de aceite de oliva y sazonar.', 'fácil', 25, 1, 'https://images.pexels.com/photos/3771807/pexels-photo-3771807.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Ensalada César Keto', 'Añadir pollo a la plancha, atún o huevo duro para aumentar la proteína. El aguacate debe estar maduro.', 'Lavary secar las hojas de lechuga, luego cortarlas o rasgarlas.. Cortar el aguacate en cubos o medias lunas.. Desmenuzar el queso feta.. Para el aderezo: mezclar aceite de oliva, vinagre de manzana y mostaza Dijon.. Combinar la lechuga, aguacate y feta en un bowl.. Rociar con el aderezo y mezclar suavemente.. Sazonar con sal y pimienta al gusto.', 'fácil', 10, 1, 'https://images.pexels.com/photos/5379352/pexels-photo-5379352.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Bowl de Atún y Aguacate', 'Para una versión más elaborada, agregar olivas, alcaparras y tomates cherry cortados.', 'Escurrir bien el atún y colocarlo en un bowl.. Mezclar el atún con la mayonesa y un poco de mostaza.. Cortar el aguacate por la mitad, quitar el hueso y cortar en cubos o láminas.. Cortar el pepino en rodajas finas.. En un plato, colocar la rúcula como base.. Añadir el aguacate y el pepino.. Colocar la mezcla de atún encima.. Sazonar con sal, pimienta y gotas de limón.', 'muy fácil', 10, 1, 'https://images.pexels.com/photos/3270893/pexels-photo-3270893.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Salmón a la Plancha con Aguacate', 'Para verificar que el salmón está cocido: debe alcanzar 63°C interno o verse opaco en el centro.', 'Sazonar el salmón con sal, pimienta y opcionalmente eneldo.. Calentar una plancha o sartén a fuego medio-alto.. Agregar mantequilla y cocinar el salmón 4-5 minutos por lado.. El salmón está listo cuando la carne se separa fácilmente con un tenedor.. Saltear las espinacas en la misma sartén con un poco de mantequilla.. Servir el salmón sobre las espinacas con aguacate al lado.. Exprimir limón fresco por encima.', 'fácil', 15, 1, 'https://images.pexels.com/photos/262959/pexels-photo-262959.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Carne Molida con Calabacín', 'Agregar especias como comino, pimentón o orégano para más sabor. El calabacín puede reemplazarse por berenjena.', 'Cortar el calabacín en rodajas o medias lunas.. Saltear el calabacín en aceite de oliva 3-4 minutos hasta que esté tierno pero crujiente.. Retirar y reservar.. En la misma sartén, cocinar la carne molida a fuego medio-alto.. Desmenuzar la carne mientras cocina, sazonar con sal y pimienta.. Cuando la carne esté dorada, agregar el calabacín de vuelta.. Espolvorear queso mozzarella y tapar 2 minutos hasta que se derrita.. Servir caliente.', 'fácil', 20, 1, 'https://images.pexels.com/photos/3616966/pexels-photo-3616966.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Wrap de Pavo con Aguacate', 'Usar hojas grandes de lechuga como ''tortilla'' para una version muy baja en carbohidratos.', 'Cocinar el pavo molido en una sartén hasta que esté bien cocido.. Sazonar con sal, pimienta y especias opcionales (ajo en polvo, cebolla en polvo).. Cortar el aguacate en láminas.. Lavar y secar las hojas de lechuga.. Cortar el tomate en rodajas finas.. Armar el wrap: colocar lechuga, pavo, aguacate y tomate sobre una superficie plana.. Agregar mayonesa al gusto.. Enrollar firmemente y cortar por la mitad.', 'fácil', 10, 1, 'https://images.pexels.com/photos/1656666/pexels-photo-1656666.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Sopa Cremosa de Coliflor', 'Esta sopa es muy versátil. Agregar bacon crujiente, queso cheddar o espinacas para variar.', 'Cortar la coliflor en floretes.. Sofreír el ajo picado en aceite de oliva hasta que esté fragante.. Agregar la coliflor y cubrir con agua o caldo.. Hervir durante 15-20 minutos hasta que esté muy tierna.. Escurrir parcialmente, reservando el líquido.. Agregar la nata y mezclar hasta obtener una consistencia cremosa.. Usar una batidora de mano para hacer puré si se desea más suave.. Sazonar con sal, pimienta y opcionalmente nutmeg.. Servir con queso parmesano rallado por encima.', 'fácil', 25, 2, 'https://images.pexels.com/photos/1188750/pexels-photo-1188750.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Bistec con Espinacas Salteadas', 'No mover el bistec mientras sella. Usar termómetro: 55°C para término medio, 60°C para tres cuartos.', 'Sacar el bistec del refrigerador 20-30 minutos antes para que esté a temperatura ambiente.. Sazonar generosamente con sal y pimienta ambos lados.. Calentar una sartén de hierro fundido a fuego alto hasta que esté muy caliente.. Sellar el bistec 3-4 minutos por lado para termino medio (o más para bien cocido).. Retirar y descansar sobre una tabla 5 minutos.. En la misma sartén, reducir el fuego y saltear el ajo en mantequilla por 1 minuto.. Agregar las espinacas y cocinar hasta que se marchiten.. Cortar el bistec en rodajas diagonales y servir con las espinacas.', 'fácil', 20, 1, 'https://images.pexels.com/photos/1251168/pexels-photo-1251168.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Salmón al Horno con Espárragos', 'Para un acabado perfecto, terminar el salmón bajo el grill 2 minutos al final.', 'Precalentar el horno a 200°C.. Forrar una bandeja con papel aluminio.. Colocar los espárragos y rociar con aceite de oliva.. Sazonar con sal y pimienta.. Colocar el salmón sobre los espárragos.. Untar el salmón con mantequilla y sazonar.. Hornear durante 15-18 minutos hasta que el salmón esté cocido.. Servir inmediatamente con un chorrito de limón.', 'fácil', 25, 1, 'https://images.pexels.com/photos/3691028/pexels-photo-3691028.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Pollo al Ajillo', 'Clásico español.', 'Freír ajo en aceite.. Agregar pollo en trozos.. Cocinar hasta dorar y agregar perejil.', 'fácil', 25, 1, 'https://images.pexels.com/photos/1464740/pexels-photo-1464740.jpeg', 'cena', true),
('Gambas al Ajillo con Pimiento', 'Usar vino blanco en lugar de vinagre para una versión más gourmet.', 'Pelar y limpiar los camarones si no están listos.. Cortar el pimiento en tiras o cubos.. Calentar el aceite de oliva en una sartén grande o wok.. Agregar el ajo y cocinar 1 minuto hasta que esté fragante.. Añadir los camarones y cocinar 2-3 minutos por lado.. Agregar el pimiento y cocinar 2 minutos más.. De-glasear con vinagre de manzana.. Sazonar con sal y pimienta, decorar con perejil.. Servir inmediatamente con pan bajo en carbohidratos si se desea.', 'fácil', 15, 1, 'https://images.pexels.com/photos/6999532/pexels-photo-6999532.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Hamburguesa Keto con Calabacín', 'Mezclar la carne con huevo para que la hamburguesa mantenga su forma mejor.', 'Formar la carne molida en una hamburguesa, sazonar con sal y pimienta.. Cortar el calabacín en rodajas gruesas (0.5 cm).. Saltear o asar las rodajas de calabacín hasta que estén doradas.. Cocinar la hamburguesa a la plancha 3-4 minutos por lado.. Agregar el queso cheddar en los últimos 2 minutos y tapar para que se derrita.. Armar: base de calabacín, lechuga, hamburguesa, mayonesa.. Tapar con otra rodaja de calabacín.. Servir con pepinillos o cebolla encurtida si se desea.', 'fácil', 20, 1, 'https://images.pexels.com/photos/2679500/pexels-photo-2679500.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Cordero con Hongos y Romero', 'El cordero es más tierno si se cocina a término medio. Usar termómetro: 60°C interno.', 'Marinar el cordero con aceite de oliva, romero, ajo, sal y pimienta por 30 minutos.. Sellar el cordero en una sartén muy caliente 2-3 minutos por lado.. Terminar en el horno a 180°C por 10-15 minutos para término medio.. Mientras tanto, saltear los champiñones en mantequilla.. Sazonar con sal, pimienta y hierbas frescas.. Dejar reposar el cordero 5 minutos antes de cortar.. Servir el cordero con los champiñones.. Acompañar con una ensalada verde ligera.', 'media', 30, 1, 'https://images.pexels.com/photos/2255777/pexels-photo-2255777.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Pechuga de Pollo al Pesto', 'El pesto casero se mantiene hasta 1 semana en el refrigerador. También sirve con calabacín en espiral.', 'Para el pesto: procesar espinacas, parmesano, almendras y ajo en procesador.. Añadir aceite de oliva gradualmente hasta obtener consistencia cremosa.. Sazonar con sal y pimienta.. Sazonar el pollo y cocinar a la plancha o horno.. Untar generosamente con pesto una vez que el pollo esté cocido.. Servir con vegetales al vapor o ensalada.', 'fácil', 25, 1, 'https://images.pexels.com/photos/5409603/pexels-photo-5409603.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Almendras con Queso Cheddar', 'Elegir almendras crudas sin sal para opción más saludable. El queso de colores intensos tiene más sabor.', 'Servir las almendras en un pequeño bowl.. Cortar o rallar el queso cheddar.. Combinar o servir por separado.. Disfrutar como snack entre comidas.', 'muy fácil', 2, 1, 'https://images.pexels.com/photos/4207904/pexels-photo-4207904.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Mitad de Aguacate con Huevo', 'Para evitar que el aguacate se vuelque, cortar una pequeña parte de la base.', 'Precalentar el horno a 180°C.. Cortar el aguacate por la mitad y quitar el hueso.. Hacer un hueco más grande en el centro del aguacate si es necesario.. Colocar el aguacate en un molde para que no se vuelque.. Romper el huevo y verter en el hueco del aguacate.. Sazonar con sal, pimienta y opcionalmente mostaza.. Hornear 12-15 minutos hasta que el huevo esté cocido.. Servir inmediatamente.', 'fácil', 10, 1, 'https://images.pexels.com/photos/557663/pexels-photo-557663.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Huevos Cocidos con Mayonesa', 'Los huevos más frescos son más difíciles de pelar. Usar huevos de al menos 1 semana.', 'Colocar los huevos en agua fría y llevar a hervir.. Una vez que hierva, cocinar 10 minutos exactos.. Inmediatamente transferir a agua con hielo para detener la cocción.. Pelarlos después de 5 minutos en agua fría.. Cortar por la mitad y untar con mayonesa.. Sazonar con sal, pimienta y mostaza.. Opcional: espolvorear con pimentón o cebollino.', 'fácil', 12, 1, 'https://images.pexels.com/photos/162967/pexels-photo-162967.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Rollitos de Jamón con Queso', 'Pueden prepararse con anticipación y mantenerse en el refrigerador hasta 2 días.', 'Extender las lonchas de jamón en una superficie plana.. Si se desea, untar una capa fina de queso crema.. Colocar el queso cheddar en un extremo.. Enrollar firmemente desde el extremo con queso.. Cortar por la mitad si se desea.. Servir a temperatura ambiente o frío.', 'muy fácil', 5, 1, 'https://images.pexels.com/photos/4109992/pexels-photo-4109992.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Palitos de Verdura con Hummus Keto', 'Preparar los vegetales con anticipación y guardarlos en agua fría crujirán más.', 'Lavar y cortar todas las verduras en palitos o flores.. Servir con el hummus bajo en carbohidratos.. Dippear los vegetales en el hummus.. Disfrutar inmediatamente.', 'fácil', 8, 1, 'https://images.pexels.com/photos/2470170/pexels-photo-2470170.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Bombones de Almendra y Chocolate', 'Agregar sal marina en escamas encima para contraste de sabor dulce-salado.', 'Tostar ligeramente las almendras en una sartén.. Derretir el chocolate con mantequilla a baño maría.. Mezclar las almendras en el chocolate fundido.. Colocar cucharadas de la mezcla en papeles para bombones o silicona.. Enfriar en el refrigerador hasta que endurezcan.. Guardar en lugar fresco.', 'media', 15, 4, 'https://images.pexels.com/photos/65882/chocolate-dark-coffee-confiserie-65882.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Queso Cottage con Piña Keto', 'El queso cottage es alto en proteína y bajo en calorías. Perfecto para snacks nocturnos.', 'Servir el queso cottage en un bowl.. Espolvorear con eritritol si se desea.. Agregar las avellanas picadas por encima.. Mezclar o comer por capas.. Disfrutar frío.', 'muy fácil', 3, 1, 'https://images.pexels.com/photos/298217/pexels-photo-298217.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Mix de Semillas y Frutos Secos', 'Este mix es rico en omega-3 y grasas saludables. Dura hasta 2 semanas en contenedor hermético.', 'Mezclar todos los ingredientes en un bowl.. Servir inmediatamente o guardar en un frasco.. Consumir como snack entre comidas.. Opcional: agregar coco rallado o chocolate negro para variar.', 'muy fácil', 2, 1, 'https://images.pexels.com/photos/5946/pexels-photo-5946.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Tostada Francesa Keto', 'El pan keto debe tener al menos 3g de net carbs por porción. Marcar con canela para sabor adicional.', 'Batir los huevos con canela y esencia de vainilla opcional.. Calentar la mantequilla en una sartén a fuego medio.. Sumergir ligeramente el pan keto en la mezcla de huevos.. Cocinar 2-3 minutos por cada lado hasta dorar.. Servir con mantequilla adicional y eritritol espolvoreado.', 'fácil', 12, 1, 'https://images.pexels.com/photos/1854652/pexels-photo-1854652.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Chaffles de Queso', 'Los chaffles se mantienen crujientes. Preparar en batch y tostar antes de usar para mejor textura.', 'Mezclar los huevos batidos con el queso mozzarella rallado.. Calentar la waflera para chaffles a temperatura media-alta.. Engrasar ligeramente con mantequilla.. Verter la mitad de la mezcla en la waflera.. Cocinar 3-4 minutos hasta que esté dorado y crujiente.. Repetir con la segunda mitad.. Servir como base para toppings dulces o salados.', 'fácil', 10, 2, 'https://images.pexels.com/photos/376464/pexels-photo-376464.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Smoothie Proteico de Chocolate', 'Usar hielo para un smoothie más frío y espeso. Esta versión funciona como comida completa.', 'Agregar todos los ingredientes en la licuadora.. Licuar a alta velocidad por 30-45 segundos.. Verificar consistencia: agregar más leche si está muy espeso.. Verter en un vaso alto.. Decorar con coco rallado o cacao nibs.', 'muy fácil', 5, 1, 'https://images.pexels.com/photos/3727250/pexels-photo-3727250.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Huevos Rancheros Keto', 'Para más proteína, agregar trozos de chorizo keto o tocino. Servir con aguacate al lado.', 'Cortar pimientos y tomates en cubos pequeños.. Saltear los vegetales en mantequilla por 3-4 minutos.. Sazonar con comino, pimentón y chile en polvo.. Hacer pozos en las verduras y romper los huevos.. Tapar y cocinar a fuego bajo 5-7 minutos.. Espolvorear queso cheddar y tapar hasta que se derrita.. Decorar con cilantro fresco si se desea.', 'fácil', 15, 1, 'https://images.pexels.com/photos/1279330/pexels-photo-1279330.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Muffins de Atún y Queso', 'Perfectos para meal prep. Duran hasta 4 días en el refrigerador. Calentar 30 segundos antes de comer.', 'Precalentar el horno a 180°C.. Escurrir bien el atún y deshacerlo.. Picar finamente los champiñones.. Mezclar huevos, nata, queso y vegetales.. Agregar el atún y sazonar.. Verter en moldes para muffins engrasados.. Hornear 15-18 minutos hasta que estén firmes.. Enfriar antes de desmoldar.', 'media', 20, 4, 'https://images.pexels.com/photos/7699696/pexels-photo-7699696.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'desayuno', true),
('Bowl California Keto', 'El pollo puede reemplazarse por camarones o tofu para variar. Añadir edamame para más proteína.', 'Cortar el pollo en tiras y cocinar a la plancha con sal y pimienta.. Mientras se cocina, preparar la base de lechuga en un bowl.. Cortar aguacate, pimiento y pepino en cubos.. Armar el bowl: lechuga base, pollo, aguacate, vegetales.. Rociar con mayonesa y sazonar.. Opcional: agregar semillas de sésamo.', 'fácil', 15, 1, 'https://images.pexels.com/photos/1640777/pexels-photo-1640777.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Berenjena a la Parmegiana', 'La berenjena al horno代替 frita reduce calorías significativamente.', 'Cortar la berenjena en rodajas de 1cm.. Salan y dejar reposar 15 minutos para eliminar amargor.. Secar y hornear a 200°C por 20 minutos.. Preparar salsa: cocinar tomates con ajo y orégano.. En una bandeja, alternar capas: berenjena, salsa, mozzarella.. Terminar con parmesano y hornear 15 minutos.. Gratinar 3-5 minutos hasta dorar.', 'media', 30, 2, 'https://images.pexels.com/photos/718742/pexels-photo-718742.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Pastel de Salmón Keto', 'Se puede hacer en muffin tins para porciones individuales. Congela bien hasta 1 mes.', 'Procesar el salmón limpio (sin espinas) hasta obtener pasta.. Mezclar con huevos, queso rallado y champiñones picados.. Sazonar con sal, pimienta y eneldo.. Verter en moldes engrasados.. Hornear a 180°C por 20-25 minutos.. Dejar enfriar 5 minutos antes de desmoldar.. Servir con ensalada verde o mayonesa.', 'media', 25, 2, 'https://images.pexels.com/photos/262959/pexels-photo-262959.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Tarta Templada de Atún', 'Esta tarta es excelente fría también. Preparar la noche anterior para lunch.', 'Precalentar el horno a 180°C.. Escurrir el atún y mezclar con huevos batidos.. Agregar espinacas cocidas, mozzarella y nata.. Sazonar con sal, pimienta y hierbas.. Verter en un molde redondo o individual.. Hornear 15-18 minutos hasta que esté firme.. Dejar reposar 5 minutos antes de cortar.', 'fácil', 20, 2, 'https://images.pexels.com/photos/3270893/pexels-photo-3270893.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Kebab de Pollo con Salsa Tzatziki', 'Para tzatziki keto: mezclar yogur griego, pepino rallado, ajo y eneldo.', 'Cortar el pollo en cubos grandes.. Marinar con aceite de oliva, ajo, orégano y limón por 15 minutos.. Ensartar en pinchos o cocinar en sartén.. Cocinar 4-5 minutos por lado hasta dorar.. Preparar los vegetales: cortar lechuga, tomate y pepino.. Servir el pollo sobre los vegetales.. Acompañar con salsa tzatziki keto.', 'media', 25, 1, 'https://images.pexels.com/photos/1656666/pexels-photo-1656666.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'almuerzo', true),
('Solomillo de Cerdo con Manzana', 'Las manzanas verdes tienen menos azúcar que las rojas. Usar термометр para punto de cocción: 60°C.', 'Sazonar el solomillo con sal, pimienta y tomillo.. Sellar en aceite de oliva a fuego alto 2-3 minutos por lado.. Reducir fuego y cocinar 10-12 minutos más.. Retirar y descansar 5 minutos.. En la misma sartén, derretir mantequilla y cocinar manzana en rodajas.. Saltear espinacas brevemente.. Cortar solomillo y servir con manzana y espinacas.', 'media', 25, 1, 'https://images.pexels.com/photos/15440244/pexels-photo-15440244.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Curry de Pollo Keto', 'La salsa curry es naturalmente keto si no se usa harina. Verificar que la pasta curry no tenga azúcar añadida.', 'Cortar pollo en trozos y marinar con pasta curry.. Sofreír ajo en aceite de coco por 1 minuto.. Agregar pollo y cocinar hasta dorar.. Añadir coliflor en floretes pequeños.. Verter nata y mezclar bien.. Cocinar a fuego bajo 15 minutos.. Sazonar y servir caliente.. Acompañar con arroz de coliflor si se desea.', 'media', 30, 2, 'https://images.pexels.com/photos/2474661/pexels-photo-2474661.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Bacalao al Horno con Tomates', 'El bacalao es muy bajo en grasa, añadir aceite de oliva es esencial para los macros.', 'Precalentar horno a 200°C.. Colocar filetes de bacalao en bandeja con papel aluminio.. Cortar tomates cherry por la mitad y distribuir alrededor.. Rociar todo con aceite de oliva y ajo picado.. Sazonar con sal, pimienta y hierbas.. Hornear 15-18 minutos hasta que el bacalao se desprenda.. Saltear espinacas y servir como guarnición.', 'fácil', 25, 1, 'https://images.pexels.com/photos/262947/pexels-photo-262947.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Stir Fry de Camarones', 'Para versión más keto, usar salsa de ostras sin azúcar o salsa de pescado.', 'Pelar y limpiar los camarones si es necesario.. Cortar calabacín y pimientos en tiras.. Calentar aceite en wok o sartén grande a fuego alto.. Agregar ajo y cocinar 30 segundos.. Añadir camarones y cocinar 2-3 minutos.. Agregar vegetales y saltear 3-4 minutos.. Sazonar con salsa de soja (tamari) y pimienta.. Servir inmediatamente.', 'fácil', 15, 1, 'https://images.pexels.com/photos/6999532/pexels-photo-6999532.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Pechuga de Pollo Rellena', 'Usartermómetro: 74°C interno. El queso mantiene todo junto mientras se cocina.', 'Hacer un corte profundo en la pechuga formando un bolsillo.. Sazonar por dentro y por fuera.. Rellenar con queso cheddar, tomates y champiñones.. Cerrar con palillos si es necesario.. Sellar en sartén con mantequilla 2 minutos por lado.. Hornear a 180°C por 20-25 minutos.. Dejar descansar 5 minutos antes de cortar.. Servir con la salsa que se forme.', 'media', 30, 1, 'https://images.pexels.com/photos/3771807/pexels-photo-3771807.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'cena', true),
('Fat Bombs de Chocolate', 'Estas son excelentes para mantener cetosis. Comer 1-2 como snack cuando se necesite energía.', 'Derretir chocolate con mantequilla a baño maría.. Agregar crema de coco y eritritol.. Mezclar hasta obtener consistencia suave.. Verter en moldes de silicone o papeles para bombones.. Refrigerar por 2 horas hasta que endurezcan.. Guardar en fridge hasta 2 semanas.', 'fácil', 15, 8, 'https://images.pexels.com/photos/65882/chocolate-dark-coffee-confiserie-65882.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Queso Horneado con Hierbas', 'Pueden prepararse varios tipos de queso. El gouda y el emmental también funcionan muy bien.', 'Precalentar el horno a 200°C.. Colocar queso cheddar en una bandeja para horno.. Hacer cortes en forma de cuadrícula sin penetrar.. Rociar con aceite de oliva y espolvorear hierbas.. Hornear 10-12 minutos hasta que esté dorado.. Servir caliente con palillos.', 'fácil', 15, 4, 'https://images.pexels.com/photos/4109992/pexels-photo-4109992.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Gelatina de Colágeno', 'El colágeno apoya la salud de articulaciones y piel. Ideal antes de dormir.', 'Disolver colágeno en agua tibia o fría.. Agregar vinagre de manzana.. Endulzar con stevia si se desea.. Beber inmediatamente o refrigerar.. También puede prepararse como gelatina con agar-agar.', 'muy fácil', 5, 1, 'https://images.pexels.com/photos/3785451/pexels-photo-3785451.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Aceitunas con Queso Feta', 'Las aceitunas son ricas en grasas monoinsaturadas. Combinar con queso aumenta la saciedad.', 'Colocar las aceitunas en un bowl.. Agregar el queso feta en cubos.. Rociar con aceite de oliva.. Sazonar con orégano si se desea.. Servir a temperatura ambiente.', 'muy fácil', 2, 1, 'https://images.pexels.com/photos/5946/pexels-photo-5946.jpeg?auto=compress&cs=tinysrgb&w=400&h=300', 'snacks', true),
('Avena con Frutos Rojos y Nueces', 'La avena es rica en fibra, ideal para energía sostenida.', 'Cocinar la avena con leche de almendra por 5 minutos.. Agregar los frutos rojos.. Decorar con nueces picadas y miel.', 'fácil', 10, 1, 'https://images.pexels.com/photos/1995089/pexels-photo-1995089.jpeg', 'desayuno', true),
